41	<p id="empty" hidden>还没有意见记录。</p>
42	<div id="ideas"></div>
43	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
44	</main><script>
45	const form = document.getElementById('idea-form');
46	const titleInput = document.getElementById('f-title');
47	const descInput = document.getElementById('f-desc');
48	const scenarioInput = document.getElementById('f-scenario');
49	const errorBox = document.getElementById('error');
50	const successBox = document.getElementById('success');
51	const emptyNote = document.getElementById('empty');
52	const list = document.getElementById('ideas');
53	const EMPTY_TEXT = '还没有意见记录。';
54	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
55	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
56	let listState = 'loading';
57	function codePoints(text) { return Array.from(text).length; }
58	function showError(message) {
59	  errorBox.textContent = message;
60	  errorBox.hidden = false;
61	  successBox.hidden = true;
62	}
63	function renderIdea(idea) {
64	  const item = document.createElement('article');
65	  item.className = 'idea';
66	  const heading = document.createElement('h3');
67	  heading.textContent = idea.title;
68	  const desc = document.createElement('p');
69	  desc.className = 'pre';
70	  desc.textContent = idea.description;
71	  item.append(heading, desc);
72	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
73	    const scenario = document.createElement('p');
74	    const label = document.createElement('strong');
75	    label.textContent = '使用场景：';
76	    const text = document.createElement('span');
77	    text.className = 'pre';
78	    text.textContent = idea.scenario;
79	    scenario.append(label, text);
80	    item.append(scenario);
81	  }
82	  const time = document.createElement('time');
83	  time.dateTime = idea.createdAt;
84	  const parsed = new Date(idea.createdAt);
85	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
86	  item.append(time);
87	  return item;
88	}
89	let remoteIdeas = [];
90	// 本页已确认保存的意见，最新提交的排在最前
91	const submittedIdeas = [];
92	function renderList() {
93	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
94	  const seen = new Set();
95	  const ordered = [];
96	  for (const idea of submittedIdeas) {
97	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
98	  }
99	  for (const idea of remoteIdeas) {
100	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
101	  }
102	  list.replaceChildren(...ordered.map(renderIdea));
103	  if (listState === 'failed') {
104	    emptyNote.textContent = LOAD_FAILED_TEXT;
105	    emptyNote.hidden = false;
106	  } else if (listState === 'ready') {
107	    emptyNote.textContent = EMPTY_TEXT;
108	    emptyNote.hidden = ordered.length > 0;
109	  } else {
110	    // 首次列表仍在加载，不能把等待误报成没有记录
111	    emptyNote.hidden = true;
112	  }
113	}
114	async function loadIdeas() {
115	  try {
116	    const res = await fetch('/api/ideas');
117	    if (!res.ok) throw new Error('load failed');
118	    const data = await res.json();
119	    remoteIdeas = Array.isArray(data.ideas) ? data.ideas : [];
120	    listState = 'ready';
121	  } catch {
122	    listState = 'failed';
123	  }
124	  renderList();
125	}
126	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
127	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
128	let editVersion = 0;
129	for (const field of [titleInput, descInput, scenarioInput]) {
130	  field.addEventListener('input', () => { editVersion += 1; });
131	}
132	function validate(title, description, scenario) {
133	  const trimmed = title.trim();
134	  if (!trimmed) return '标题不能为空。';
135	  if (codePoints(trimmed) > 120) return '标题最多 120 个字符。';
136	  if (!description.trim()) return '详细说明不能为空。';
137	  if (codePoints(description) > 5000) return '详细说明最多 5000 个字符。';
138	  if (codePoints(scenario) > 1000) return '使用场景最多 1000 个字符。';
139	  return null;
140	}
141	form.addEventListener('submit', async (event) => {
142	  event.preventDefault();
143	  errorBox.hidden = true;
144	  successBox.hidden = true;
145	  const title = titleInput.value;
146	  const description = descInput.value;
147	  const scenario = scenarioInput.value;
148	  const submittedVersion = editVersion;
149	  const problem = validate(title, description, scenario);
150	  if (problem) { showError(problem); return; }
151	  let res;
152	  try {
153	    res = await fetch('/api/ideas', {
154	      method: 'POST',
155	      headers: { 'content-type': 'application/json' },
156	      body: JSON.stringify({ title, description, scenario })
157	    });
158	  } catch {
159	    showError('网络错误，提交未成功，请重试。');
160	    return;
161	  }
162	  let data = null;
163	  try { data = await res.json(); } catch { data = null; }
164	  if (!res.ok || !data || !data.idea) {
165	    showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
166	    return;
167	  }
168	  // 只有等待期间没有继续编辑（包括改回原文、清空字段也算编辑）才清空表单；
169	  // 否则完整保留此刻的草稿，成功提示与列表仍按本次提交的记录更新
170	  if (editVersion === submittedVersion) form.reset();
171	  successBox.textContent = '提交成功，你的意见已保存。';
172	  successBox.hidden = false;
173	  // 只把已确认保存的意见并入列表，随后统一渲染，避免与首次列表响应相互覆盖
174	  submittedIdeas.unshift(data.idea);
175	  renderList();
176	});
177	loadIdeas();
178	</script></html>`;
179	const args: string[] = process.argv.slice(2);
180	const help: string = `FeatureHarbor - 产品意见与公开路线图
181	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
182	       node server.ts --help
183	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
184	Port 0 selects an available port.
185	`;
186	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
187	  process.stdout.write(help);
188	  process.exit(args.length === 0 ? 2 : 0);
189	}
190	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
191	let host: string = '127.0.0.1';
192	let port: number = 8080;
193	let dataDir: string = 'data';
194	while (args.length) {
195	  const flag = args.shift();
196	  const value = args.shift();
197	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
198	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
199	  }
200	  if (flag === '--host') host = value;
201	  else if (flag === '--port') {
202	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
203	    port = Number(value);
204	  } else dataDir = value;
205	}
206	mkdirSync(dataDir, { recursive: true });
207	const dataFile = join(dataDir, 'ideas.json');
208	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
209	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
210	}
211	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
212	  const body = options.html ? String(value) : JSON.stringify(value);
213	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
214	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
215	  res.end(body);
216	}
217	function codePoints(text: string): number {
218	  return Array.from(text).length;
219	}
220	function readIdeas(): unknown[] {
221	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
222	  if (!Array.isArray(records)) throw new Error('Invalid record list');
223	  return records;
224	}
225	function saveIdeas(records: unknown[]): void {
226	  const tempFile = `${dataFile}.tmp`;
227	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
228	  renameSync(tempFile, dataFile);
229	}
230	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
231	  const chunks: Buffer[] = [];
232	  let size = 0;
233	  for await (const chunk of req as AsyncIterable<Buffer>) {
234	    size += chunk.length;
235	    if (size > MAX_BODY_BYTES) {
236	      respond(res, 400, { error: '请求体过大' });
237	      req.destroy();
238	      return;
239	    }
240	    chunks.push(chunk);
241	  }
242	  let payload: unknown;
243	  try {
244	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
245	  } catch {
246	    respond(res, 400, { error: '请求体不是有效的 JSON' });
247	    return;
248	  }
249	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
250	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
251	    return;
252	  }
253	  const body = payload as Record<string, unknown>;
254	  for (const field of ['title', 'description'] as const) {
255	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
256	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
257	  }
258	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
259	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
260	    return;
261	  }
262	  const title = (body.title as string).trim();
263	  const description = body.description as string;
264	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
265	  if (!title) { respond(res, 400, { error: '标题去掉首尾空白后不能为空' }); return; }
266	  if (codePoints(title) > MAX_TITLE) { respond(res, 400, { error: `标题最多 ${MAX_TITLE} 个字符` }); return; }
267	  if (!description.trim()) { respond(res, 400, { error: '详细说明必须包含非空白内容' }); return; }
268	  if (codePoints(description) > MAX_DESCRIPTION) { respond(res, 400, { error: `详细说明最多 ${MAX_DESCRIPTION} 个字符` }); return; }
269	  if (codePoints(scenario) > MAX_SCENARIO) { respond(res, 400, { error: `使用场景最多 ${MAX_SCENARIO} 个字符` }); return; }
270	  const idea = {
271	    id: randomUUID(),
272	    title,
273	    description,
274	    scenario,
275	    createdAt: new Date().toISOString(),
276	  };
277	  let records: unknown[];
278	  try {
279	    records = readIdeas();
280	  } catch {
281	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
282	    return;
283	  }
284	  records.unshift(idea);
285	  try {
286	    saveIdeas(records);
287	  } catch {
288	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
289	    return;
290	  }
291	  respond(res, 201, { idea });
292	}
293	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
294	  let route: string;
295	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
296	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
297	  if (route === '/api/ideas') {
298	    if (req.method === 'POST') {
299	      handleCreateIdea(req, res).catch(() => {
300	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
301	      });
302	      return;
303	    }
304	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
305	    try {
306	      respond(res, 200, { [RESOURCE]: readIdeas() });
307	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
308	    return;
309	  }
310	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
311	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
312	  respond(res, 200, { status: 'ok', product: PRODUCT });
313	});
314	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
315	server.listen(port, host, (): void => {
316	  const address = server.address();
317	  if (address && typeof address !== 'string') {
318	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
319	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
320	  }
321	});
322	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
323	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
324	}
