import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';

let server: StartedServer;
let pageScript: string;

before(async () => {
  server = await startServer();
  const res = await fetch(`${server.origin}/`);
  const html = await res.text();
  const start = html.indexOf('<script>');
  const end = html.lastIndexOf('</script>');
  pageScript = html.slice(start + '<script>'.length, end);
});

after(async () => {
  await server.stop();
  removeDataDir(server);
});

interface El {
  tagName: string; hidden: boolean; value: string; dateTime: string; children: El[];
  text: string | null; textContent: string;
  listeners: Record<string, Array<(e: unknown) => unknown>>;
  append(...n: El[]): void; replaceChildren(...n: El[]): void;
  addEventListener(t: string, fn: (e: unknown) => unknown): void; reset(): void;
}
function makeElement(tag: string): El {
  const node: any = {
    tagName: tag.toUpperCase(), hidden: false, value: '', dateTime: '', children: [], text: null,
    listeners: {},
    append(...n: El[]) { this.children.push(...n); },
    replaceChildren(...n: El[]) { this.children = [...n]; },
    addEventListener(t: string, fn: (e: unknown) => unknown) { (this.listeners[t] ??= []).push(fn); },
    reset() {},
  };
  Object.defineProperty(node, 'textContent', {
    get() { return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join(''); },
    set(v: unknown) { this.text = String(v); },
  });
  return node as El;
}
function gate() {
  let resolve!: (v: unknown) => void; let reject!: (e: Error) => void;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}
function jsonResponse(status: number, body: unknown): any {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}
const flush = (): Promise<void> => new Promise((r) => setTimeout(r, 0));
let seq = 0;
function idea(p: Record<string, unknown> = {}): Record<string, unknown> {
  seq += 1;
  return { id: `id-${seq}`, title: `t${seq}`, description: `d${seq}`, scenario: '', createdAt: '2026-01-01T00:00:00.000Z', ...p };
}
const EMPTY_TEXT = '还没有意见记录。';
const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';

class Harness {
  els: Record<string, El> = {}; gets: any[] = []; posts: any[] = [];
  constructor(script: string) {
    const byId = new Map<string, El>();
    const reg = (id: string, tag: string, hidden = false): El => { const n = makeElement(tag); n.hidden = hidden; byId.set(id, n); this.els[id] = n; return n; };
    const titleInput = reg('f-title', 'input'); reg('f-desc', 'textarea'); const scenarioInput = reg('f-scenario', 'textarea');
    reg('idea-form', 'form');
    // re-register form first? need form listeners; do proper:
    byId.delete('idea-form');
    const form = reg('idea-form', 'form');
    reg('error', 'p', true); reg('success', 'p', true); reg('empty', 'p', true); reg('ideas', 'div');
    form.reset = () => { titleInput.value = ''; (this.els['f-desc']).value = ''; scenarioInput.value = ''; };
    const documentMock = { getElementById: (id: string) => byId.get(id)!, createElement: (t: string) => makeElement(t) };
    const fetchMock = (_u: unknown, init?: { method?: string }) => {
      const g = gate();
      if ((init?.method ?? 'GET') === 'POST') this.posts.push(g); else this.gets.push(g);
      return g.promise;
    };
    vm.runInContext(script, vm.createContext({ console, document: documentMock, fetch: fetchMock }), { filename: 'p.js' });
  }
  articles(): El[] { return this.els.ideas.children.filter((n) => n.tagName === 'ARTICLE'); }
  setForm(v: { title?: string; description?: string; scenario?: string }) {
    if (v.title !== undefined) this.els['f-title'].value = v.title;
    if (v.description !== undefined) this.els['f-desc'].value = v.description;
    if (v.scenario !== undefined) this.els['f-scenario'].value = v.scenario;
  }
  submit() { return this.els['idea-form'].listeners.submit[0]({ preventDefault() {} }); }
}

